/*
 * A090243  Permutation of natural numbers generated by 4-rowed array shown
 *          below.
 * https://oeis.org/A090243
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) is obtained by diagonally traversing a 4‑row array *
 *            defined as follows. * For a column c (c = 1, 2, 3, …) and a row
 *            r (1 ≤ r ≤ 4), * base = 4*(c-1) + 1 // the first number in the
 *            block * If c ≡ 1 (mod 3) the row order is 0,1,2,3. * Otherwise
 *            the row order is 2,1,0,3. * The value at (c,r) is...
 * Range:     u8 n <= 72, u16 n <= 72, u32 n <= 72, u64 n <= 72, u128 n <= 72,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* n is 1‑based.  Find the diagonal d containing the nth term. */
    idx_t d = 2;          /* diagonal index starts at 2 (c=1,r=1) */
    idx_t cum = 0;        /* number of terms before current diagonal */

    while (1) {
        idx_t len = (d - 1 <= 4) ? (d - 1) : 4;   /* terms in diagonal d */
        if (cum + len >= n)
            break;          /* nth term is in diagonal d */
        cum += len;
        ++d;
    }

    /* Row r within this diagonal (1‑based). */
    idx_t r = n - cum;          /* 1 ≤ r ≤ min(4, d-1) */
    idx_t c = d - r;            /* column index (1‑based) */

    /* Compute the array value at (c,r). */
    idx_t base_idx = 4 * (c - 1) + 1;   /* integer base (within idx_t) */
    seq_t base = (seq_t)base_idx;

    seq_t offset;
    if (c % 3 == 1) {
        /* ascending order (base + (r-1)) */
        offset = (seq_t)(r - 1);
    } else {
        /* order 3,2,1,4 → offsets 2,1,0,3 for rows 1..4 */
        switch (r) {
            case 1: offset = 2; break;
            case 2: offset = 1; break;
            case 3: offset = 0; break;
            case 4: offset = 3; break;
            default: offset = 0;  /* should never occur */
        }
    }

    return base + offset;
}
